def parse():
 out={}
 for line in STORIES.strip().splitlines():
  if not line.strip():continue
  word,setting,anchor,actions,transfer=line.split('|')
  aa=actions.split(';');n=len(re.findall('[A-Za-z]',word))
  if len(aa)!=n:print('COUNT',word,n,len(aa))
  out[word]={'meaning_anchor':anchor,'setting':setting,'actions':aa,'transfer':transfer,'contrast':'字母按位置逐一编码；重复形象保留出现次数。故事不是词源或发音规则。'}
 return out

if __name__=='__main__':
 p=BASE/'g4.json';d=json.loads(p.read_text(encoding='utf-8'));d['stories']=parse();p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 target={e['spelling'] for b in d['books'] for e in b['entries']}
 print('stories',len(d['stories']),'missing',len(target-set(d['stories'])))
 print(' / '.join(sorted(target-set(d['stories']))))
